def is_palindrome(s):
    kiri, kanan = 0, len(s) - 1
    while kiri < kanan:
        while kiri < kanan and not s[kiri].isalnum():
            kiri += 1
        while kiri < kanan and not s[kanan].isalnum():
            kanan -= 1
        if s[kiri].lower() != s[kanan].lower():
            return False
        kiri += 1
        kanan -= 1
    return True
